import React, { useState, useEffect } from 'react';
import './Carrito.css';
import { FaTrash } from 'react-icons/fa';
import { getCartItems, removeFromCart, updateCartItemQuantity } from '../Carrito_Localstorang/CaritoLocalstorang';
import { Wallet, initMercadoPago } from '@mercadopago/sdk-react';
import { useDispatch } from 'react-redux';
import { Compra } from '../../../Redux/Actions/Usuario/Action-user';
import alertify from 'alertifyjs';
import 'alertifyjs/build/css/alertify.css';

const Carrito = () => {
  const [loading, setLoading] = useState(true);
  const [cartItems, setCartItems] = useState([]);
  const [ordersData, setOrdersData] = useState([]);
  const [showCart, setShowCart] = useState(true);
  const dispatch = useDispatch();

  initMercadoPago('APP_USR-ca102d50-c4cd-4152-8963-dee46e25e589');

  useEffect(() => {
    const timer = setTimeout(() => {
      setLoading(false);
    }, 3000);

    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
    const items = getCartItems();
    setCartItems(items);
  }, []);

  const handleRemoveItem = (id) => {
    removeFromCart(id);
    setCartItems(getCartItems());
  };

  const handleUpdateQuantity = (id, quantity) => {
    updateCartItemQuantity(id, quantity);
    setCartItems(getCartItems());
  };

  const calculateTotal = () => {
    return cartItems.reduce((total, item) => total + item.costo * item.quantity, 0);
  };

  const handleCrearOrden = async () => {
    try {
      const groupedItems = cartItems.reduce((acc, item) => {
        if (!acc[item.tienda]) {
          acc[item.tienda] = [];
        }
        acc[item.tienda].push(item);
        return acc;
      }, {});

      const promises = [];

      for (const [tienda, items] of Object.entries(groupedItems)) {
        const totalCost = items.reduce((total, item) => total + item.costo * item.quantity, 0);
        const cantidad = items.reduce((total, item) => total + item.quantity, 0);
        const descriptions = items.map(item => item.descripcion).join(', ');

        const compra = await dispatch(Compra(descriptions, cantidad, totalCost));
        const orderData = {
          tienda,
          urlPago: compra.urlPago,
        };
        setOrdersData(prevState => [...prevState, orderData]);

        alertify.alert('Orden creada', `Orden para la tienda ${tienda} creada correctamente.`);
      }

      setShowCart(false);
    } catch (error) {
      console.error(error);
      alertify.alert('Error', 'No se pudo crear la preferencia de pago.');
    }
  };

  const renderOrdenesPorTienda = () => {
    return ordersData.map(order => (
      <div key={order.tienda} className="orden-por-tienda">
        <h2>Orden para tienda {order.tienda}</h2>
        <button
          className="btn-pagar-tienda"
          onClick={() => {
            window.open(order.urlPago, '_blank');
          }}
        >
          Pagar
        </button>
      </div>
    ));
  };

  return (
    <div>
      {loading && <div>Loading...</div>}
      <div className="CarritoBody">
        {showCart ? (
          <div className="Carrito-cards">
            <h1>Carrito de Compras</h1>
            {cartItems.length === 0 ? (
              <div>No hay elementos en el carrito</div>
            ) : (
              cartItems.map(item => (
                <div key={item.id} className="carrito-item">
                  <img src={item.url} alt={item.descripcion} className="carrito-imagen" />
                  <div className="carrito-descripcion">{item.descripcion}</div>
                  <div className="carrito-botones">
                    <div className="carrito-boton" onClick={() => handleRemoveItem(item.id)}>
                      <FaTrash />
                    </div>
                    <div className="carrito-boton" onClick={() => handleUpdateQuantity(item.id, item.quantity - 1)}>
                      -
                    </div>
                    <div className="carrito-cantidad">{item.quantity}</div>
                    <div className="carrito-boton" onClick={() => handleUpdateQuantity(item.id, item.quantity + 1)}>
                      +
                    </div>
                    <div className="carrito-total">Total: ${item.costo * item.quantity}</div>
                  </div>
                </div>
              ))
            )}
            <div className="carrito-total">
              <div>Total a Pagar: ${calculateTotal()}</div>
              <button className="carrito-boton-pagar" onClick={handleCrearOrden}>Crear Orden</button>
            </div>
          </div>
        ) : (
          <div className="ordenes-por-tienda">
            {renderOrdenesPorTienda()}
          </div>
        )}
      </div>
    </div>
  );
};

export default Carrito;
